local mature = {}
for low in MATURE:gmatch("%S+") do mature[low] = true end
local filtering = false
-- Words the player dropped off the d-pad: never guessed.
local forgot = NONE
local function Barred(low) return forgot[low] or (filtering and (mature[low] or lex.mature[low])) end
local total = 1

local function KeyOf(word)
    local out = {}
    for c in word:gmatch(UTF8) do
        c = FOLD[c] or LowerCase(c)
        local digit = digitOf[c]
        if digit then
            out[#out + 1] = digit
        elseif c ~= "'" then
            return nil
        end
    end
    return table.concat(out)
end
D.KeyOf = KeyOf

-- The first place in sorted[lo..hi) at or past x.
local function Lower(x, lo, hi)
    while lo < hi do
        local mid = math.floor((lo + hi) / 2)
        if sorted[mid] < x then lo = mid + 1 else hi = mid end
    end
    return lo
end

function D.SetLayout(name)
    local groups = ns.LAYOUTS[name] or ns.LAYOUTS.letters
    wipe(digitOf)
    for g, letters in ipairs(groups) do
        for c in letters:gmatch(UTF8) do digitOf[c] = tostring(g) end
    end
    for i = 1, #words do
        keys[i] = KeyOf(words[i]) or ""
        order[i] = i
    end
    table.sort(order, function(a, b)
        if keys[a] ~= keys[b] then return keys[a] < keys[b] end
        return a < b
    end)
    for j, id in ipairs(order) do sorted[j] = keys[id] end
    for _, e in ipairs(extras) do e.key = KeyOf(e.word) end
    if name == "letters" or not ns.LAYOUTS[name] then
        rare = lettersRare
    else
        local lists = {}
        for _, lines in pairs(lettersRare) do
            for word, count in lines:gmatch("\n%d+ (%S+) (%d+)") do
                local key = KeyOf(word)
                local head = key and sub(key, 1, 4)
                if head and #head >= 3 then
                    lists[head] = lists[head] or {}
                    local list = lists[head]
                    list[#list + 1] = key .. " " .. word .. " " .. count
                end
            end
        end
        rare = {}
        for head, list in pairs(lists) do
            table.sort(list)
            rare[head] = "\n" .. table.concat(list, "\n") .. "\n"
        end
    end
    wipe(rareHeads)
    for head in pairs(rare) do rareHeads[sub(head, 1, 3)] = true end
    lex.rare, lex.layout = rare, name
    -- Each box's letters for exact letters: its own, then the language's accented ones of them.
    lex.boxes = {}
    for g, letters in ipairs(groups) do
        local box = {}
        for c in letters:gmatch(UTF8) do box[#box + 1] = c end
        for c in lex.accents:gmatch(UTF8) do
            if digitOf[FOLD[c] or c] == tostring(g) then box[#box + 1] = c end
        end
        lex.boxes[g] = box
    end
end

-- A language's list from its data: words (word and count lines, commonest first), pairs, rare, and for a
-- language folder's: mature (its filter's words), joins (elided words that take no space after: l'),
-- accents (its accented letters, for exact letters), layouts (optional non-Latin letter groups).
local function NewList(code, data)
    local l = { code = code, words = {}, lows = {}, keys = {}, prob = {}, idOf = {}, order = {}, sorted = {}, cut = {},
        rareHeads = {}, mature = {}, joins = {}, total = 0, accents = data.accents or "",
        layouts = data.layouts or LATIN_LAYOUTS, digitOf = {} }
    for word, count in data.words:gmatch("(%S+) (%d+)") do
        local id = #l.words + 1
        l.words[id], l.lows[id], l.prob[id] = word, LowerCase(word), tonumber(count)
        l.cut[id] = find(word, "['\128-\255]") ~= nil
        l.idOf[l.lows[id]] = l.idOf[l.lows[id]] or id
        l.total = l.total + l.prob[id]
    end
    for id = 1, #l.words do l.prob[id] = l.prob[id] / l.total end
    l.pairLines, l.lettersRare = data.pairs, data.rare
    for low in (data.mature or ""):gmatch("%S+") do l.mature[low] = true end
    for low in (data.joins or ""):gmatch("%S+") do l.joins[low] = true end
    data.words = nil
    return l
end

-- The list of the language typed in (ns.TypingLanguage: its folder loaded, English where it is not there).
function D.Build()
    local code = ns.TypingLanguage()
    if code == "enUS" and not ns.wordLists.enUS then
        ns.wordLists.enUS = { words = ns.WORD_DATA, pairs = ns.PAIR_DATA, rare = ns.RARE_DATA }
        ns.WORD_DATA, ns.PAIR_DATA, ns.RARE_DATA = nil, nil, nil
    end
    local l = lexicons[code] or NewList(code, ns.wordLists[code])
    lexicons[code] = l
    if lex ~= l then
        lex = l
        words, lows, keys, prob, idOf, order, sorted = l.words, l.lows, l.keys, l.prob, l.idOf, l.order, l.sorted
        pairLines, cut, rare, rareHeads, lettersRare, total = l.pairLines, l.cut, l.rare, l.rareHeads, l.lettersRare, l.total
        digitOf = l.digitOf
        after.id = false
    end
    ns.LAYOUTS = l.layouts
    if not l.rare or l.layout ~= ns.db.layout then D.SetLayout(ns.db.layout) end
end

-- A rarer word's own spelling (capitals kept) from its lowercase, or nil when the list lacks it.
local function RareForm(low)
    local key = KeyOf(low)
    local lines = key and rare[sub(key, 1, 4)]
    local at = lines and find(lines, "\n" .. key .. " ", 1, true)
    while at do
        local k, word, nextAt = match(lines, "^\n(%d+) (%S+) %d+()", at)
        if k ~= key then return nil end
        if LowerCase(word) == low then return word end
        at = nextAt
    end
end

function D.Known(low) return idOf[low] ~= nil or RareForm(low) ~= nil end

function D.Built() return lex ~= nil end

function D.Code() return lex.code end

-- An elided word, written onto the next with no space: l'.
function D.Joins(low) return lex.joins[low] end

function D.Box(group) return lex.boxes[group] end

-- A listed word as the list writes it (its capital, a noun's in German), from its lowercase.
function D.Form(low)
    local id = idOf[low]
    return id and words[id] or RareForm(low) or low
end

-- The i-th commonest word when it is one for typing practice: lowercase letters, two or more, never one
-- the mature filter holds. Key length counts letters, not UTF-8 bytes.
function D.PracticeWord(i)
    local word = words[i]
    if word and word == lows[i] and #keys[i] >= 2 and not find(word, "['%s]") and not mature[word] and not lex.mature[word] then
        return word
    end
end

-- The player's counts and the words outside the list: names (name -> chance) and the player's own new words.
function D.Refresh(names)
    local db = ns.db
    own.count, own.total = db.learned, 0
    for _, count in pairs(db.learned) do own.total = own.total + count end
    own.mix = OWN_SHARE * math.min(1, own.total / OWN_FULL)
    wipe(own.next)
    wipe(own.ctx)
    for pair, count in pairs(db.pairs) do
        local prev, low = pair:match("^(%S+) (%S+)$")
        if prev then
            own.next[prev] = own.next[prev] or {}
            own.next[prev][low] = count
            own.ctx[prev] = (own.ctx[prev] or 0) + count
        end
    end
    wipe(extras)
    local seen = {}
    -- ours: shorthand, game words and the player's own stand beside a listed word of the same letters.
    local function Add(word, chance, ours)
        local low = LowerCase(word)
        local key = KeyOf(word)
        if seen[low] or (not ours and D.Known(low)) or not key or key == "" then return end
        seen[low] = true
        extras[#extras + 1] = { word = word, low = low, key = key, chance = chance }
    end
    for name, chance in pairs(names or {}) do Add(name, chance) end
    local function Like(low) return idOf[low] and prob[idOf[low]] or FALLBACK_CHANCE end
    for word in (db.myWords or ""):gmatch("%S+") do Add(word, Like(OWN_WORD_LIKE), true) end
    -- English's own extra shorthand and places; another language's list holds its own.
    if lex.code == "enUS" then
        for word in CHAT_MORE:gmatch("%S+") do Add(word, Like(CHAT_LIKE), true) end
        for word in GAME_MORE:gmatch("%S+") do Add(word, Like(GAME_LIKE), true) end
    end
    for low in pairs(db.learned) do Add(db.forms[low] or low, 1e-7) end
end

-- An elided word and the word it was written onto (l'ami) count as that word (ami) where the list lacks the two as one.
local function PrevId(prevLow)
    if prevLow == "<s>" then return 0 end
    return prevLow and (idOf[prevLow] or idOf[match(prevLow, "'([^']+)$")])
end

-- The word before's followers: counts by id, how often it is followed and by how many words, the likeliest few.
local function Followers(prevId)
    if after.id ~= prevId then
        after.id, after.total, after.kinds = prevId, 0, 0
        wipe(after.counts)
        wipe(after.top)
        local line = prevId and pairLines[prevId]
        if line then
            local total, kinds, rest = match(line, "^(%d+) (%d+) ?(.*)$")
            after.total, after.kinds = tonumber(total), tonumber(kinds)
            for id, n in rest:gmatch("(%d+) (%d+)") do
                id = tonumber(id)
                after.counts[id] = tonumber(n)
                if #after.top < FOLLOW_KEPT then after.top[#after.top + 1] = id end
            end
        end
    end
    return after.total > 0 and after or nil
end

-- A word's chance after the word before (Witten-Bell: what follows it often counts most, a word never seen after
-- it only by as much as that word is followed by new ones), then the player's own.
local function Score(id, low, chance, prevId, prevLow)
    local p = chance or prob[id]
    local h = Followers(prevId)
    if h then p = ((id and h.counts[id] or 0) + h.kinds * p) / (h.total + h.kinds) end
    if own.total > 0 then
        local u = (own.count[low] or 0) / own.total
        local after = prevLow and own.next[prevLow]
        if after then u = 0.5 * u + 0.5 * (after[low] or 0) / own.ctx[prevLow] end
        p = (1 - own.mix) * p + own.mix * u
    end
    return p > 0 and log(p) or -60
end

local function Keep(word, low, score)
    local n, cap = best.n, best.cap
    for i = 1, n do
        if best.lows[i] == low then
            if score <= best.scores[i] then return end
            for j = i, n - 1 do
                best.words[j], best.lows[j], best.scores[j] = best.words[j + 1], best.lows[j + 1], best.scores[j + 1]
            end
            n = n - 1
            break
        end
    end
    if n == cap and score <= best.scores[n] then
        best.n = n
        return
    end
    local at = math.min(n + 1, cap)
    while at > 1 and best.scores[at - 1] < score do
        if at <= cap then
            best.words[at], best.lows[at], best.scores[at] = best.words[at - 1], best.lows[at - 1], best.scores[at - 1]
        end
        at = at - 1
    end
    best.words[at], best.lows[at], best.scores[at] = word, low, score
    best.n = math.min(n + 1, cap)
end

local function Result()
    local out = {}
    for i = 1, best.n do out[i] = best.words[i] end
    best.n = 0
    return out
end

-- A word's first n letters, an apostrophe inside them kept ("don't" at 4).
local function StemOf(word, n)
    local out, letters = {}, 0
    for c in word:gmatch(UTF8) do
        if letters == n then break end
        out[#out + 1] = c
        if c ~= "'" then letters = letters + 1 end
    end
    local stem = table.concat(out)
    -- all of an elided word's letters: the word, its apostrophe too
    if #stem + 1 == #word and sub(word, -1) == "'" then return word end
    return stem
end

local function AddStem(stem, score, clean)
    stems[stem] = (stems[stem] or 0) + exp(score)
    if clean then cleanStems[stem] = true end
end

-- The likeliest letters so far: what the chat box shows. RT then steps through the readings of exactly what was
-- flicked before those taking a flick as missed.
local function Stems()
    best.n, best.cap = 0, STEMS_KEPT
    -- In letter order: readings of the same chance keep one order from one time to the next.
    local n = 0
    for stem in pairs(stems) do
        n = n + 1
        stemOrder[n] = stem
    end
    for i = #stemOrder, n + 1, -1 do stemOrder[i] = nil end
    table.sort(stemOrder)
    for i = 1, n do Keep(stemOrder[i], LowerCase(stemOrder[i]), stems[stemOrder[i]]) end
    wipe(stems)
    local out = Result()
    best.cap = GUESSES
    local ordered = { out[1] }
    for pass = 1, 2 do
        for i = 2, #out do
            if (cleanStems[out[i]] ~= nil) == (pass == 1) then ordered[#ordered + 1] = out[i] end
        end
    end
    wipe(cleanStems)
    return ordered
end

local function Exact(word, low, score)
    if score > exact.score then exact.word, exact.low, exact.score = word, low, score end
end

-- Whether a rarer word starts with these digits of n flicks; from four digits on, the block holding them. Rarer
-- words take one misflick at most: with two they could never outrank a common word.
local function RareLines(prefix, n, subs)
    if n < RARE_FROM or subs > 1 then return nil end
    local digits = #prefix
    if digits < 3 then return true end
    if digits == 3 then return n == 3 and rare[prefix] or (n > 3 and rareHeads[prefix]) end
    local lines = rare[sub(prefix, 1, 4)]
    return lines and (digits == 4 or find(lines, "\n" .. prefix, 1, true)) and lines
end

-- The rarer words whose key starts with these n digits; at three only whole words (that block holds no more).
local function RareLeaf(lines, prefix, n, cost, maxExtra, prevId, prevLow)
    local at = find(lines, "\n" .. prefix, 1, true)
    while at do
        local key, word, count, nextAt = match(lines, "^\n(%d+) (%S+) (%d+)()", at)
        if not key or sub(key, 1, n) ~= prefix then return end
        local low = LowerCase(word)
        if not Barred(low) then
            local extra = #key - n
            local score = Score(nil, low, count / total, prevId, prevLow) + cost
            if extra <= maxExtra then Keep(word, low, score - extra * EXTRA_COST) end
            if extra == 0 and cost == 0 then Exact(word, low, score) end
            local stem = find(word, "['\128-\255]") and StemOf(word, n) or sub(word, 1, n)
            AddStem(stem, score + (extra == 0 and WHOLE_WORD or 0), cost == 0)
        end
        at = nextAt
    end
end

-- The flicks a digit at a time over the sorted keys, each misflick tried where allowed (one from two flicks on,
-- two from four): a branch ends as soon as no word starts that way, so a long run costs no more than a word.
local function Walk(seq, n, i, prefix, lo, hi, cost, subs, prevId, prevLow)
    if i > n then
        local maxExtra = subs > 0 and SUB_EXTRA or math.min(MAX_EXTRA, n + 2)
        for j = lo, hi - 1 do
            local id = order[j]
            if not Barred(lows[id]) then
                local extra = #keys[id] - n
                local score = Score(id, lows[id], nil, prevId, prevLow) + cost
                if extra <= maxExtra then Keep(words[id], lows[id], score - extra * EXTRA_COST) end
                if extra == 0 and cost == 0 then
                    Exact(words[id], lows[id], score)
                    if not pairLines[id] and score > tag.score then tag.word, tag.low, tag.score = words[id], lows[id], score end
                end
                local stem = cut[id] and StemOf(words[id], n) or sub(words[id], 1, n)
                AddStem(stem, score + (extra == 0 and WHOLE_WORD or 0), cost == 0)
            end
        end
        local lines = RareLines(prefix, n, subs)
        if lines then RareLeaf(lines, prefix, n, cost, maxExtra, prevId, prevLow) end
        return
    end
    local flicked = byte(seq, i)
    local canSub = n >= 2 and (subs == 0 or (subs == 1 and n >= 4))
    local alt = ALT[flicked]
    for a = -1, canSub and 5 or -1, 2 do
        local digit, step = flicked, 0
        if a > 0 then digit, step = alt[a], alt[a + 1] end
        local p = prefix .. char(digit)
        local l = Lower(p, lo, hi)
        local h = Lower(p .. "9", l, hi)
        local taken = subs + (a > 0 and 1 or 0)
        if l < h or RareLines(p, n, taken) then
            Walk(seq, n, i + 1, p, l, h, cost + step, taken, prevId, prevLow)
        end
    end
end

-- An extra word's cost for these flicks: its misflicks and letters past them; nil when it cannot be meant.
local function Match(key, seq)
    local n = #seq
    local extra = #key - n
    if extra < 0 or extra > MAX_EXTRA then return nil end
    local cost, subs = 0, 0
    for i = 1, n do
        local a, b = byte(seq, i), byte(key, i)
        if a ~= b then
            subs = subs + 1
            local c = SUB[a * 100 + b]
            if not c or n < 2 or (subs > 1 and n < 4) or subs > 2 then return nil end
            cost = cost + c
        end
    end
    if subs > 0 and extra > SUB_EXTRA then return nil end
    return cost - extra * EXTRA_COST
end

-- A word owed a d-pad slot goes in at the last free one, or over the guess there; the slot the next may take.
local function Slot(guesses, pick, at)
    if not pick.word then return at end
    for _, word in ipairs(guesses) do
        if LowerCase(word) == pick.low then return at end
    end
    guesses[math.min(#guesses + 1, at)] = pick.word
    return at - 1
end

-- For a string of flicked digits (a misflick or two allowed on longer words): the best whole-word guesses, then
-- the likeliest letters so far, one per flick.
function D.Decode(seq, prevLow, drop)
    best.n = 0
    wipe(stems)
    wipe(cleanStems)
    local n = #seq
    if n == 0 then return Result(), {} end
    exact.word, exact.score = nil, -math.huge
    tag.word, tag.score = nil, -math.huge
    filtering, forgot = ns.db.matureFilter == true, ns.db.forgot
    local prevId = PrevId(prevLow)
    Walk(seq, n, 1, "", 1, #sorted + 1, 0, 0, prevId, prevLow)
    -- A box only passed through on a swing across (drop: its place in the flicks) may not have been meant: the
    -- flicks without it are read too, at a cost, so a word they spell wins only where the full flicks spell none.
    local alt = drop and drop > 1 and drop <= n and sub(seq, 1, drop - 1) .. sub(seq, drop + 1)
    if alt then Walk(alt, n - 1, 1, "", 1, #sorted + 1, D.DROP_COST, 0, prevId, prevLow) end
    for _, e in ipairs(extras) do
        local less = alt and e.key and not forgot[e.low] and Match(e.key, alt)
        if less then Keep(e.word, e.low, Score(nil, e.low, e.chance, prevId, prevLow) + less + D.DROP_COST) end
    end
    for _, e in ipairs(extras) do
        local cost = e.key and not forgot[e.low] and Match(e.key, seq)
        if cost then
            local score = Score(nil, e.low, e.chance, prevId, prevLow) + cost
            Keep(e.word, e.low, score)
            local extra = #e.key - n
            AddStem(StemOf(e.word, n), score + extra * EXTRA_COST + (extra == 0 and WHOLE_WORD or 0),
                sub(e.key, 1, n) == seq)
            if e.key == seq then
                Exact(e.word, e.low, score)
                if score > tag.score then tag.word, tag.low, tag.score = e.word, e.low, score end
            end
        end
    end
    local guesses = Result()
    if n >= 3 then
        local at = Slot(guesses, tag, GUESSES)
        Slot(guesses, exact, at)
    end
    return guesses, Stems()
end

-- A name's cost for these flicks: the flicks are its first letters, a misflick or two allowed; any length after.
local function NameCost(key, seq)
    local n = #seq
    if #key < n then return nil end
    local cost, subs = 0, 0
    for i = 1, n do
        local a, b = byte(seq, i), byte(key, i)
        if a ~= b then
            subs = subs + 1
            local c = SUB[a * 100 + b]
            if not c or n < 2 or (subs > 1 and n < 4) or subs > 2 then return nil end
            cost = cost + c
        end
    end
    return cost
end

-- The people (from ns.WhisperNames) whose name these flicks start, best first; each keyed by its first word.
function D.MatchNames(list, seq)
    best.n = 0
    for _, e in ipairs(list) do
        if e.key == nil then e.key = KeyOf(e.label:match("^%S+") or "") or false end
        local cost = e.key and NameCost(e.key, seq)
        if cost then Keep(e, LowerCase(e.label) .. "\0" .. e.tellTarget, log(e.chance) + cost) end
    end
    return Result()
end

-- The likeliest next words after prevLow ("<s>" for a message's first).
function D.Next(prevLow)
    best.n = 0
    local prevId = PrevId(prevLow)
    local h = Followers(prevId)
    filtering, forgot = ns.db.matureFilter == true, ns.db.forgot
    for _, id in ipairs(h and h.top or NONE) do
        if not Barred(lows[id]) then Keep(words[id], lows[id], Score(id, lows[id], nil, prevId, prevLow)) end
    end
    local after = own.next[prevLow or "<s>"]
    if after then
        for low in pairs(after) do
            local id = idOf[low]
            local word = id and words[id] or ns.db.forms[low] or RareForm(low) or low
            if not Barred(low) then Keep(word, low, Score(id, low, not id and 1e-7 or nil, prevId, prevLow)) end
        end
    end
    for id = 1, GUESSES do
        if best.n >= GUESSES then break end
        if not Barred(lows[id]) then Keep(words[id], lows[id], Score(id, lows[id], nil, prevId, prevLow) - 20) end
    end
    return Result()
end

